import "glacia/styles.css";
// Glacia — progress
// Copied with `npx glacia add progress`. Edit freely; it is yours.
// Shared helpers come from the `glacia` package, which must be installed.

import {
  forwardRef,
  type ComponentPropsWithoutRef,
  type ElementRef,
} from "react";
import { Progress as RadixProgress } from "radix-ui";
import { cx } from "glacia/internal/cx";

export const Progress = forwardRef<
  ElementRef<typeof RadixProgress.Root>,
  ComponentPropsWithoutRef<typeof RadixProgress.Root>
>(function Progress({ className, value, ...props }, ref) {
  return (
    <RadixProgress.Root
      ref={ref}
      className={cx("gl-glass gl-progress", className)}
      {...props}
    >
      <RadixProgress.Indicator
        className="gl-progress-indicator"
        style={{ transform: `translateX(-${100 - (value || 0)}%)` }}
      />
    </RadixProgress.Root>
  );
});
